import{_ as n,a,c as s,ac as o}from"./chunks/framework.BSuaGltH.js";const d=JSON.parse('{"title":"第一册：英语初阶 · 单元 2 复习与自测 · 第32–38课","description":"L25–L48 原创练习和答案解析。","frontmatter":{"title":"第一册：英语初阶 · 单元 2 复习与自测 · 第32–38课","description":"L25–L48 原创练习和答案解析。","splitFrom":"life/english/new-concept/book-1/unit-02/review.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"读写与对话练习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第一册：英语初阶 · 单元 2 复习与自测","summary":"L25–L48 原创练习和答案解析。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · 单元 2 复习与自测 · 第25–31课","link":"/life/english/new-concept/book-1/unit-02/review-part-01"},"next":{"text":"第一册：英语初阶 · 单元 2 复习与自测 · 第39–45课","link":"/life/english/new-concept/book-1/unit-02/review-part-03"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · 单元 2 复习与自测 · 第25–31课","link":"/life/english/new-concept/book-1/unit-02/review-part-01"},"next":{"text":"第一册：英语初阶 · 单元 2 复习与自测 · 第39–45课","link":"/life/english/new-concept/book-1/unit-02/review-part-03"}},"headers":[],"relativePath":"life/english/new-concept/book-1/unit-02/review-part-02.md","filePath":"life/english/new-concept/book-1/unit-02/review-part-02.md"}'),r={name:"life/english/new-concept/book-1/unit-02/review-part-02.md"};function i(t,e,l,g,h,p){return a(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="第一册-英语初阶-·-单元-2-复习与自测-·-第32–38课" tabindex="-1">第一册：英语初阶 · 单元 2 复习与自测 · 第32–38课 <a class="header-anchor" href="#第一册-英语初阶-·-单元-2-复习与自测-·-第32–38课" aria-label="Permalink to &quot;第一册：英语初阶 · 单元 2 复习与自测 · 第32–38课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-1/unit-02/review">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-1/unit-02/overview">单元导读</a> · <a href="/life/english/new-concept/book-1/unit-02/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-1/unit-02/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-1/unit-02/review">单元复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="lesson-32-·-现在进行时单数" tabindex="-1">Lesson 32 · 现在进行时单数 <a class="header-anchor" href="#lesson-32-·-现在进行时单数" aria-label="Permalink to &quot;Lesson 32 · 现在进行时单数 {#lesson-32-·-现在进行时单数}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Is the cat sleeping under the chair?</p><h3 id="练习-1-7" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-7" aria-label="Permalink to &quot;练习 1 {#练习-1-7}&quot;">​</a></h3><p>把 sleep 写成 ing 形式。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> sleeping</p><p><strong>解析：</strong> 按本课规则判断：现在进行时由 am/is/are + 动词 ing 构成，用于描述说话时或现阶段正在进行的动作。he/she/it 用 is，I 用 am。否定词 not 放在 be 后；问句将 be 提前。以不发音 e 结尾的动词通常去 e 加 ing，如 make → making，不能只写动词 ing 而漏掉 be。</p></details><p><strong>表达迁移：</strong> 围绕“描述此刻一个人正在做的事情”写两至三句，再读给同伴听。至少使用一次现在进行时单数，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Is the cat sleeping under the chair? Nora is reading beside the window.</p><p>Is 从 is sleeping 中前置形成问句；the cat 是主语，under the chair 说明睡觉的位置。 Nora 为单数主语，is reading 构成现在进行时；beside the window 只提供地点，不参与谓语变化。</p></details><p><a href="/life/english/new-concept/book-1/unit-02/lesson-032">回看本课</a></p><h2 id="lesson-33-·-现在进行时复数" tabindex="-1">Lesson 33 · 现在进行时复数 <a class="header-anchor" href="#lesson-33-·-现在进行时复数" aria-label="Permalink to &quot;Lesson 33 · 现在进行时复数 {#lesson-33-·-现在进行时复数}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The children are drawing by the pond.</p><h3 id="练习-1-8" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-8" aria-label="Permalink to &quot;练习 1 {#练习-1-8}&quot;">​</a></h3><p>填 be：The children ___ drawing.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> are</p><p><strong>解析：</strong> 按本课规则判断：复数主语搭配 are + 动词 ing。what are they doing 询问活动，不问职业。并列两个动作且主语相同时可共享 be，如 They are singing and dancing。run、swim 等短元音加单辅音结尾的动词通常双写尾辅音加 ing；walk、read 不需要双写。用 now 强调当前场景。</p></details><p><strong>表达迁移：</strong> 围绕“观察户外多人活动”写两至三句，再读给同伴听。至少使用一次现在进行时复数，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The children are drawing by the pond. Two dogs are running across the field.</p><p>The children 是复数主语，are drawing 表示现在正在进行的动作；by the pond 表在池塘旁边。 Two dogs 是复数主语；run 双写 n 后加 ing，are running 构成进行时；across the field 表横穿田野。</p></details><p><a href="/life/english/new-concept/book-1/unit-02/lesson-033">回看本课</a></p><h2 id="lesson-34-·-现在进行时复数" tabindex="-1">Lesson 34 · 现在进行时复数 <a class="header-anchor" href="#lesson-34-·-现在进行时复数" aria-label="Permalink to &quot;Lesson 34 · 现在进行时复数 {#lesson-34-·-现在进行时复数}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Two dogs are running across the field.</p><h3 id="练习-1-9" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-9" aria-label="Permalink to &quot;练习 1 {#练习-1-9}&quot;">​</a></h3><p>把 run 改成 ing 形式。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> running</p><p><strong>解析：</strong> 按本课规则判断：复数主语搭配 are + 动词 ing。what are they doing 询问活动，不问职业。并列两个动作且主语相同时可共享 be，如 They are singing and dancing。run、swim 等短元音加单辅音结尾的动词通常双写尾辅音加 ing；walk、read 不需要双写。用 now 强调当前场景。</p></details><p><strong>表达迁移：</strong> 围绕“观察户外多人活动”写两至三句，再读给同伴听。至少使用一次现在进行时复数，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Two dogs are running across the field. The children are drawing by the pond.</p><p>Two dogs 是复数主语；run 双写 n 后加 ing，are running 构成进行时；across the field 表横穿田野。 The children 是复数主语，are drawing 表示现在正在进行的动作；by the pond 表在池塘旁边。</p></details><p><a href="/life/english/new-concept/book-1/unit-02/lesson-034">回看本课</a></p><h2 id="lesson-35-·-位置与方向介词" tabindex="-1">Lesson 35 · 位置与方向介词 <a class="header-anchor" href="#lesson-35-·-位置与方向介词" aria-label="Permalink to &quot;Lesson 35 · 位置与方向介词 {#lesson-35-·-位置与方向介词}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> A narrow bridge crosses the river.</p><h3 id="练习-1-10" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-10" aria-label="Permalink to &quot;练习 1 {#练习-1-10}&quot;">​</a></h3><p>选择 across/along：沿河散步 walk ___ the river.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> along</p><p><strong>解析：</strong> 按本课规则判断：in、on、under、between 主要交代位置；into 表进入内部，out of 表离开内部，across 表横穿表面，along 表沿着。描述地图时先确定参照物，不能把所有中文“在”都翻成 in。存在句介绍地标，进行时说明人正在沿什么路线移动，两类句子可在同一段描述中配合。</p></details><p><strong>表达迁移：</strong> 围绕“描述村庄布局与移动路线”写两至三句，再读给同伴听。至少使用一次位置与方向介词，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>A narrow bridge crosses the river. The visitors are walking along the river.</p><p>A narrow bridge 是单数主语，crosses 是一般现在时第三人称形式；the river 是 crosses 的宾语。 The visitors 为复数主语，are walking 描述正在步行；along the river 说明沿河线性移动，而不是横渡河流。</p></details><p><a href="/life/english/new-concept/book-1/unit-02/lesson-035">回看本课</a></p><h2 id="lesson-36-·-位置与方向介词" tabindex="-1">Lesson 36 · 位置与方向介词 <a class="header-anchor" href="#lesson-36-·-位置与方向介词" aria-label="Permalink to &quot;Lesson 36 · 位置与方向介词 {#lesson-36-·-位置与方向介词}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The visitors are walking along the river.</p><h3 id="练习-1-11" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-11" aria-label="Permalink to &quot;练习 1 {#练习-1-11}&quot;">​</a></h3><p>选择 in/into：从门外走进屋内 go ___ the house.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> into</p><p><strong>解析：</strong> 按本课规则判断：in、on、under、between 主要交代位置；into 表进入内部，out of 表离开内部，across 表横穿表面，along 表沿着。描述地图时先确定参照物，不能把所有中文“在”都翻成 in。存在句介绍地标，进行时说明人正在沿什么路线移动，两类句子可在同一段描述中配合。</p></details><p><strong>表达迁移：</strong> 围绕“描述村庄布局与移动路线”写两至三句，再读给同伴听。至少使用一次位置与方向介词，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The visitors are walking along the river. A narrow bridge crosses the river.</p><p>The visitors 为复数主语，are walking 描述正在步行；along the river 说明沿河线性移动，而不是横渡河流。 A narrow bridge 是单数主语，crosses 是一般现在时第三人称形式；the river 是 crosses 的宾语。</p></details><p><a href="/life/english/new-concept/book-1/unit-02/lesson-036">回看本课</a></p><h2 id="lesson-37-·-be-going-to-表计划" tabindex="-1">Lesson 37 · be going to 表计划 <a class="header-anchor" href="#lesson-37-·-be-going-to-表计划" aria-label="Permalink to &quot;Lesson 37 · be going to 表计划 {#lesson-37-·-be-going-to-表计划}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> We are going to paint the bench tomorrow.</p><h3 id="练习-1-12" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-12" aria-label="Permalink to &quot;练习 1 {#练习-1-12}&quot;">​</a></h3><p>填原形：We are going to ___ (paint) the bench.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> paint</p><p><strong>解析：</strong> 按本课规则判断：be going to + 动词原形表示事先计划或有迹象的将来；be 随主语变化。be + 动词 ing 在本课表示当前进行。I am making 描述正在做，I am going to make 描述准备做。问计划时将 be 提前：What are you going to make?。to 后不能再用 making，时间词帮助确定语境。</p></details><p><strong>表达迁移：</strong> 围绕“区分眼前动作与未来计划”写两至三句，再读给同伴听。至少使用一次be going to 表计划，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>We are going to paint the bench tomorrow. I am measuring the shelf now.</p><p>We are going to paint 表计划，paint 用原形；the bench 为宾语，tomorrow 把计划放在明天。 I am measuring 是现在进行时，now 强调眼前动作；它与计划结构 going to measure 的时间视角不同。</p></details><p><a href="/life/english/new-concept/book-1/unit-02/lesson-037">回看本课</a></p><h2 id="lesson-38-·-be-going-to-表计划" tabindex="-1">Lesson 38 · be going to 表计划 <a class="header-anchor" href="#lesson-38-·-be-going-to-表计划" aria-label="Permalink to &quot;Lesson 38 · be going to 表计划 {#lesson-38-·-be-going-to-表计划}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> I am measuring the shelf now.</p><h3 id="练习-1-13" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-13" aria-label="Permalink to &quot;练习 1 {#练习-1-13}&quot;">​</a></h3><p>填 be：I ___ measuring the shelf now.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> am</p><p><strong>解析：</strong> 按本课规则判断：be going to + 动词原形表示事先计划或有迹象的将来；be 随主语变化。be + 动词 ing 在本课表示当前进行。I am making 描述正在做，I am going to make 描述准备做。问计划时将 be 提前：What are you going to make?。to 后不能再用 making，时间词帮助确定语境。</p></details><p><strong>表达迁移：</strong> 围绕“区分眼前动作与未来计划”写两至三句，再读给同伴听。至少使用一次be going to 表计划，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>I am measuring the shelf now. We are going to paint the bench tomorrow.</p><p>I am measuring 是现在进行时，now 强调眼前动作；它与计划结构 going to measure 的时间视角不同。 We are going to paint 表计划，paint 用原形；the bench 为宾语，tomorrow 把计划放在明天。</p></details><p><a href="/life/english/new-concept/book-1/unit-02/lesson-038">回看本课</a></p>',60)])])}const m=n(r,[["render",i]]);export{d as __pageData,m as default};
